create type crawl_task_status as enum ('PENDING','RUNNING','SUCCESS','RETRY','FAILED','ACCESS_LIMITED');
create table crawl_jobs (id uuid primary key, mode text not null check (mode in ('ASIN','KEYWORD')), marketplace text not null, status text not null, created_at timestamptz not null default now());
create table crawl_tasks (id uuid primary key, job_id uuid not null references crawl_jobs(id), asin text, url text not null, status crawl_task_status not null default 'PENDING', attempt_count int not null default 0, last_error_code text, checkpoint_at timestamptz, unique(job_id,url));
create table products (asin text not null, marketplace text not null, product_url text, title text, brand text, category jsonb, images jsonb not null default '[]', parent_asin text, updated_at timestamptz not null default now(), primary key (asin, marketplace));
create table product_snapshots (id uuid primary key, asin text not null, marketplace text not null, captured_at timestamptz not null, current_price numeric, list_price numeric, currency text, rating numeric, review_count int, bsr int, availability text, seller text, fulfilled_by text, prime boolean, raw_capture_path text not null);
create table crawl_errors (id uuid primary key, task_id uuid not null references crawl_tasks(id), code text not null, message text not null, details jsonb, created_at timestamptz not null default now());
